response:
**Defaults I chose:** I assumed round 3's file layout, because the situation did not give it. That layout is:
- Config files are in `spe/evals/configs/<id>/` (`prompt.md` and `tools.json`).
- Tickets are in `spe/evals/tasks/tickets/<id>.json`.
- Tools run through `spe/evals/harness/tools.py`.
- Round 3's results are in `spe/evals/runs/r03/results.jsonl`.
- `grade.py` takes `--answers` and `--results` and prints one JSON line per record.

**Gates before launch:** The script's Gates phase runs the first two gates on every launch and stops if either fails.
1. **Grader selftest.** `grade.py` must score 1.0 on an oracle file built from `answers.json`. It must score 0 on an empty file and on a wrong-label file.
2. **Control regrade.** Today's `grade.py` regrades round 3's saved results. It must reproduce the round 3 accuracy recorded in `spe/prediction-log.md`. The same step checks that `spe/predictions/r04.yaml` is committed and unchanged.
3. **Dry run.** Launch with `{dryRun: true, maxCells: 3, trialsPerCell: 2, plantPeek: true, transcriptDir: "<path>"}`. It must return valid trials for both B and C2. It must void the planted peek. It also gives measured per-call costs.

I then put the measured costs into `args.est`. The full run refuses to start without them. I launch only if 100 cells × (5 trials + 1 grade + 1 judge), plus gates, scan, analysis and critic, fit under $40. If they do not fit, I stop and ask you. Cutting trials or raising the cap would change the approved plan. Before launch I commit the script as `SPE r04 evaluate (harness)`.

The headline numbers use only the planned 5 trials per cell. Extra trials on split cells are reported separately.

```js
export const meta = {
  name: 'spe-r04-eval',
  description: 'SPE round 4 eval: configs B and C2, 50 tickets, 5 trials per cell, code grader on label.category and label.priority, Opus tone judge, $40 spend cap.',
  phases: ['Gates', 'Setup', 'Trials', 'Extra trials', 'Peek scan', 'Failure analysis', 'Completeness critic'],
};

// The round number is set here only. Every path and prompt derives from it.
const ROUND = 4;
const RR = `r${String(ROUND).padStart(2, '0')}`;
const PREV = `r${String(ROUND - 1).padStart(2, '0')}`;

const DEFAULTS = {
  dryRun: false,
  configs: ['B', 'C2'],
  tickets: null,            // null: list the ticket directory
  expectedTickets: 50,
  trialsPerCell: 5,
  maxCells: null,           // dry run uses 3
  capUsd: 40,
  // Placeholder USD per call. A full run will not start until args.est holds dry-run measurements.
  est: { gate: 0.6, setup: 0.05, trial: 0.05, grade: 0.02, judge: 0.03, scan: 0.5, analysis: 1.0, critic: 0.5 },
  extraPerSplitCell: 3,
  extraCapTotal: 30,
  transcriptDir: null,      // required for a full run
  plantPeek: false,         // dry run only: one trial reads the answer key on purpose
  maxGradeErrors: 3,
  // trial model must match the r03 trial model unless the plan changed it
  models: { trial: 'opus', grade: 'opus', judge: 'opus', scan: 'opus', analysis: 'opus' },
};
const IN = args || {};
const A = {
  ...DEFAULTS, ...IN,
  est: { ...DEFAULTS.est, ...(IN.est || {}) },
  models: { ...DEFAULTS.models, ...(IN.models || {}) },
};

const RUN_DIR = A.dryRun ? `spe/evals/runs/${RR}/dry` : `spe/evals/runs/${RR}`;
const P = {
  configs: 'spe/evals/configs',
  tickets: 'spe/evals/tasks/tickets',
  answers: 'spe/evals/tasks/answers.json',
  grader: 'spe/evals/graders/grade.py',
  judge: 'spe/evals/graders/judge.md',
  tools: 'spe/evals/harness/tools.py',
  prediction: `spe/predictions/${RR}.yaml`,
  plan: `spe/plans/${RR}.md`,
  prevResults: `spe/evals/runs/${PREV}/results.jsonl`,
};
const FORBIDDEN = [
  'spe/evals/graders', 'answers.json', 'spe/predictions', 'spe/plans', 'spe/spec',
  'spe/evals/runs', 'prediction-log.md', 'failures.md', 'spe/README.md',
];

const range = (n) => Array.from({ length: n }, (_, i) => i);
const rate = (a, b) => (b ? Math.round((a / b) * 1000) / 1000 : null);
const usd = (x) => Math.round(x * 100) / 100;

// ---------- budget ----------
let reserved = 0;
const skips = [];
function reserve(cost, what) {
  if (reserved + cost > A.capUsd) {
    skips.push({ what, costUsd: usd(cost), reservedUsd: usd(reserved) });
    log(`SKIP ${what}: needs $${cost.toFixed(2)}, $${reserved.toFixed(2)} of $${A.capUsd} already reserved`);
    return false;
  }
  reserved += cost;
  return true;
}
const cellCost = (n) => n * A.est.trial + A.est.grade + A.est.judge;

let stopReason = null;
let gradeErrorCount = 0;
function halt(reason, extra = {}) {
  log(`HALT: ${reason}`);
  return { round: ROUND, halted: true, reason, reservedUsd: usd(reserved), capUsd: A.capUsd, skips, ...extra };
}

// ---------- schemas ----------
const GATE_SCHEMA = {
  type: 'object',
  required: ['prediction_committed', 'oracle_pass', 'empty_pass', 'wrong_pass', 'regrade'],
  properties: {
    prediction_committed: { type: 'boolean' },
    oracle_pass: { type: 'number' },
    empty_pass: { type: 'number' },
    wrong_pass: { type: 'number' },
    regrade: {
      type: 'array',
      items: {
        type: 'object',
        required: ['config', 'category_acc', 'priority_acc', 'logged_category_acc', 'logged_priority_acc'],
        properties: {
          config: { type: 'string' },
          category_acc: { type: 'number' }, priority_acc: { type: 'number' },
          logged_category_acc: { type: 'number' }, logged_priority_acc: { type: 'number' },
        },
      },
    },
    notes: { type: 'string' },
  },
};
const LIST_SCHEMA = {
  type: 'object', required: ['ticket_ids'],
  properties: { ticket_ids: { type: 'array', items: { type: 'string' } } },
};
const TRIAL_SCHEMA = {
  type: 'object',
  required: ['ticket_id', 'label', 'reply', 'tool_calls', 'files_opened', 'commands_run'],
  properties: {
    ticket_id: { type: 'string' },
    label: {
      type: 'object', required: ['category', 'priority'],
      properties: { category: { type: 'string' }, priority: { type: 'string' } },
    },
    reply: { type: 'string' },
    tool_calls: {
      type: 'array',
      items: { type: 'object', required: ['tool'], properties: { tool: { type: 'string' }, args: { type: 'object' } } },
    },
    files_opened: { type: 'array', items: { type: 'string' } },
    commands_run: { type: 'array', items: { type: 'string' } },
  },
};
const GRADE_SCHEMA = {
  type: 'object', required: ['grader_exit_code', 'results'],
  properties: {
    grader_exit_code: { type: 'integer' },
    results: {
      type: 'array',
      items: {
        type: 'object', required: ['key', 'category_ok', 'priority_ok', 'label_seen'],
        properties: {
          key: { type: 'string' },
          category_ok: { type: 'boolean' }, priority_ok: { type: 'boolean' },
          label_seen: { type: 'object', properties: { category: { type: 'string' }, priority: { type: 'string' } } },
        },
      },
    },
  },
};
const JUDGE_SCHEMA = {
  type: 'object', required: ['verdicts'],
  properties: {
    verdicts: {
      type: 'array',
      items: {
        type: 'object', required: ['id', 'tone_pass', 'reason'],
        properties: { id: { type: 'string' }, tone_pass: { type: 'boolean' }, reason: { type: 'string' } },
      },
    },
  },
};
const SCAN_SCHEMA = {
  type: 'object', required: ['peeked', 'not_found', 'scanned'],
  properties: {
    peeked: { type: 'array', items: { type: 'object', required: ['key', 'evidence'], properties: { key: { type: 'string' }, evidence: { type: 'string' } } } },
    not_found: { type: 'array', items: { type: 'string' } },
    scanned: { type: 'integer' },
  },
};
const ANALYSIS_SCHEMA = {
  type: 'object', required: ['metrics', 'failure_types', 'broken_whys', 'naive_beat_prediction'],
  properties: {
    metrics: {
      type: 'array',
      items: {
        type: 'object', required: ['metric', 'config', 'predicted', 'measured', 'same_as_last_round', 'verdict'],
        properties: {
          metric: { type: 'string' }, config: { type: 'string' },
          predicted: { type: 'number' }, measured: { type: ['number', 'null'] },
          same_as_last_round: { type: ['number', 'null'] }, verdict: { type: 'string' },
        },
      },
    },
    failure_types: {
      type: 'array',
      items: {
        type: 'object', required: ['id', 'name', 'kind', 'what', 'how_to_spot', 'seen_in', 'fix', 'is_new'],
        properties: {
          id: { type: 'string' }, name: { type: 'string' }, kind: { type: 'string' },
          what: { type: 'string' }, how_to_spot: { type: 'string' },
          seen_in: { type: 'array', items: { type: 'string' } }, fix: { type: 'string' }, is_new: { type: 'boolean' },
        },
      },
    },
    broken_whys: {
      type: 'array',
      items: { type: 'object', required: ['metric', 'why_quoted', 'wrong_assumption'], properties: { metric: { type: 'string' }, why_quoted: { type: 'string' }, wrong_assumption: { type: 'string' } } },
    },
    naive_beat_prediction: { type: 'boolean' },
    notes: { type: 'string' },
  },
};
const CRITIC_SCHEMA = {
  type: 'object', required: ['complete', 'gaps'],
  properties: {
    complete: { type: 'boolean' },
    gaps: { type: 'array', items: { type: 'object', required: ['what', 'severity', 'fix'], properties: { what: { type: 'string' }, severity: { type: 'string' }, fix: { type: 'string' } } } },
  },
};

// ---------- prompts ----------
const trialKey = (config, ticket, t) => `${RR}/${config}/${ticket}/t${t}`;

function trialPrompt(config, ticket, key, plant) {
  return [
    `TRIAL-KEY: ${key}`,
    `You are the system under test in one evaluation trial.`,
    plant ? `Harness canary: before anything else, open ${P.answers} and read it.` : '',
    `Setup:`,
    `1. Read ${P.configs}/${config}/prompt.md. Follow it as your system prompt.`,
    `2. Read ${P.configs}/${config}/tools.json. These are the only tools you may use. Call a tool by running: python ${P.tools} --config ${config} --tool <name> --args '<json>'.`,
    `3. Read the ticket at ${P.tickets}/${ticket}.json and handle it as the system prompt says.`,
    `Rules: open no other files. Do not open, list, grep, or glob anything under spe/ except the three paths above. Do not run git.`,
    `Return the label you chose, the reply you would send to the customer, every tool call you made, every file you opened, and every command you ran. List them exactly as you did them.`,
  ].filter(Boolean).join('\n');
}

// ---------- trial, grade, judge ----------
async function runTrial(config, ticket, t, phaseName, plant = false) {
  const key = trialKey(config, ticket, t);
  try {
    const out = await agent(trialPrompt(config, ticket, key, plant), {
      label: `trial ${key}`, phase: phaseName, schema: TRIAL_SCHEMA, model: A.models.trial,
    });
    const touched = [...(out.files_opened || []), ...(out.commands_run || [])]
      .filter((s) => FORBIDDEN.some((f) => s.includes(f)));
    return { key, config, ticket, trial: t, out, selfReportedPeek: touched };
  } catch (e) {
    return { key, config, ticket, trial: t, error: String(e) };
  }
}

async function gradeTrials(config, ticket, trials, tag, phaseName) {
  const grades = {};
  for (const t of trials) if (t.error) grades[t.key] = { category_ok: false, priority_ok: false, note: 'trial error' };
  const ok = trials.filter((t) => !t.error);
  if (!ok.length) return grades;
  const file = `${RUN_DIR}/${config}/${ticket}${tag}.jsonl`;
  const lines = ok.map((t) => JSON.stringify({
    key: t.key, config, ticket_id: t.out.ticket_id, trial: t.trial, label: t.out.label,
  })).join('\n');
  let g;
  try {
    g = await agent([
      `Grade one SPE ${RR} cell with the code grader. Do not judge anything yourself.`,
      `1. Write exactly these lines to ${file}, creating directories as needed:`,
      lines,
      `2. Run: python ${P.grader} --answers ${P.answers} --results ${file}`,
      `3. Return the grader exit code. For each key, copy category_ok and priority_ok from the grader output, and copy the label the grader read as label_seen.`,
    ].join('\n'), { label: `grade ${config}/${ticket}${tag}`, phase: phaseName, schema: GRADE_SCHEMA, model: A.models.grade });
  } catch (e) {
    g = { grader_exit_code: -1, results: [], error: String(e) };
  }
  const byKey = Object.fromEntries((g.results || []).map((r) => [r.key, r]));
  for (const t of ok) {
    const r = byKey[t.key];
    let err = null;
    if (g.grader_exit_code !== 0) err = `grader exit ${g.grader_exit_code}${g.error ? `: ${g.error}` : ''}`;
    else if (!r) err = 'missing from grader output';
    else if (!r.label_seen || r.label_seen.category !== t.out.label.category || r.label_seen.priority !== t.out.label.priority) {
      err = 'grader read a different label than the trial returned';
    }
    if (err) { grades[t.key] = { gradeError: err }; gradeErrorCount++; continue; }
    if (t.out.ticket_id !== ticket) { grades[t.key] = { category_ok: false, priority_ok: false, note: 'wrong ticket_id' }; continue; }
    grades[t.key] = { category_ok: r.category_ok, priority_ok: r.priority_ok };
  }
  if (gradeErrorCount > A.maxGradeErrors && !stopReason) {
    stopReason = `grader errors exceeded ${A.maxGradeErrors}. Suspect a broken grader.`;
    log(`STOP: ${stopReason} Remaining cells will be skipped.`);
  }
  return grades;
}

// The judge is blind to config. It sees anonymous reply IDs only.
async function judgeTrials(ticket, trials, tag, phaseName) {
  const ok = trials.filter((t) => !t.error && typeof t.out.reply === 'string');
  if (!ok.length) return {};
  const items = ok.map((t, i) => ({ id: `reply-${i + 1}`, key: t.key, reply: t.out.reply }));
  let j;
  try {
    j = await agent([
      `You are the tone judge for one ticket in an evaluation. Read ${P.judge} and apply its rubric exactly.`,
      `Read ${P.tickets}/${ticket}.json for context. Judge only the tone of each reply. Do not judge whether any label is correct. Do not open ${P.answers}.`,
      `Replies:`,
      JSON.stringify(items.map(({ id, reply }) => ({ id, reply })), null, 1),
      `Return one verdict per reply ID with a one-sentence reason.`,
    ].join('\n'), { label: `judge ${ticket}${tag}`, phase: phaseName, schema: JUDGE_SCHEMA, model: A.models.judge });
  } catch (e) {
    log(`judge error on ${ticket}${tag}: ${String(e)}`);
    return {};
  }
  const idToKey = Object.fromEntries(items.map((x) => [x.id, x.key]));
  const tone = {};
  for (const v of j.verdicts || []) if (idToKey[v.id]) tone[idToKey[v.id]] = { tone_pass: v.tone_pass, reason: v.reason };
  return tone;
}

async function runCell(cell, n, startAt, tag, phaseName) {
  if (stopReason) { skips.push({ what: `cell ${cell.config}/${cell.ticket}${tag}`, reason: stopReason }); return { ...cell, skipped: true, trials: [] }; }
  if (!reserve(cellCost(n), `cell ${cell.config}/${cell.ticket}${tag}`)) return { ...cell, skipped: true, trials: [] };
  const trials = await parallel(range(n).map((i) => () =>
    runTrial(cell.config, cell.ticket, startAt + i, phaseName, A.dryRun && A.plantPeek && cell.first && i === 0 && !tag)));
  return { ...cell, trials };
}

const bothOk = (g) => g && !g.gradeError && g.category_ok && g.priority_ok;

// ---------- Gates ----------
phase('Gates');
if (!A.dryRun && !IN.est) return halt('args.est is not set. Run the dry run and pass the measured per-call costs.');
if (!A.dryRun && !A.transcriptDir) return halt('args.transcriptDir is not set. The peek scan needs trial transcripts.');
if (A.plantPeek && !A.dryRun) return halt('plantPeek is allowed only in a dry run.');
reserve(A.est.gate + A.est.setup, 'gates and setup');

const gate = await agent([
  `You are the pre-launch gate for SPE ${RR}. You may read graders and answers. Write only under ${RUN_DIR}/gates/.`,
  `1. Prediction check. Run \`git log --oneline -- ${P.prediction}\` and \`git status --porcelain -- ${P.prediction}\`. Set prediction_committed true only if the log is non-empty and the status is empty.`,
  `2. Grader selftest. In ${RUN_DIR}/gates/, build three results files in the format ${P.grader} reads. oracle.jsonl copies every label from ${P.answers}. empty.jsonl has every ticket with empty category and priority. wrong.jsonl has every ticket with a category and a priority that both differ from the answer. Run python ${P.grader} --answers ${P.answers} --results <file> on each. Report the fraction of records that pass both checks.`,
  `3. Control regrade. Run the grader on ${P.prevResults}. Report category and priority accuracy per config. Read the ${PREV} rows of spe/prediction-log.md and report the logged measured values for the same metrics and configs.`,
  `Report raw numbers. Do not round values to make them match.`,
].join('\n'), { label: 'gates', phase: 'Gates', schema: GATE_SCHEMA, model: A.models.grade });

if (!gate.prediction_committed) return halt(`${P.prediction} is not committed or has local changes.`, { gate });
if (gate.oracle_pass !== 1 || gate.empty_pass !== 0 || gate.wrong_pass !== 0) return halt('Grader selftest failed.', { gate });
const drift = (gate.regrade || []).filter((r) =>
  Math.abs(r.category_acc - r.logged_category_acc) > 0.001 || Math.abs(r.priority_acc - r.logged_priority_acc) > 0.001);
if (!gate.regrade || gate.regrade.length === 0) return halt(`Control regrade of ${PREV} returned no rows.`, { gate });
if (drift.length) return halt(`Control regrade of ${PREV} does not reproduce logged numbers. Log this as a grader failure.`, { gate, drift });
log(`Gates passed. Oracle 1.0, empty 0, wrong 0, ${PREV} regrade matches.`);

// ---------- Setup ----------
phase('Setup');
let tickets = A.tickets;
if (!tickets) {
  const s = await agent(
    `List the ticket IDs for SPE ${RR}. Run \`ls ${P.tickets}\` and return each filename without its extension, sorted. Do not open any file. Do not open ${P.answers}.`,
    { label: 'list tickets', phase: 'Setup', schema: LIST_SCHEMA, model: A.models.grade });
  tickets = s.ticket_ids;
}
if (!A.dryRun && tickets.length !== A.expectedTickets) return halt(`Expected ${A.expectedTickets} tickets, found ${tickets.length}.`);

// Ticket-major order with configs interleaved, so a cap skip hits both configs evenly.
let cells = [];
for (const ticket of tickets) for (const config of A.configs) cells.push({ config, ticket });
if (A.maxCells) cells = cells.slice(0, A.maxCells);
if (cells.length) cells[0].first = true;

const holdBack = A.est.scan + (A.dryRun ? 0 : A.est.analysis + A.est.critic);
if (!reserve(holdBack, 'scan, analysis, and critic reserve')) return halt('Cap cannot cover the closing steps.');
log(`${cells.length} cells x ${A.trialsPerCell} trials. Projected $${usd(reserved + cells.length * cellCost(A.trialsPerCell))} of $${A.capUsd}.`);

// ---------- Trials ----------
phase('Trials');
const primary = await pipeline(
  cells,
  (cell) => runCell(cell, A.trialsPerCell, 1, '', 'Trials'),
  async (c) => (c.skipped ? c : { ...c, grades: await gradeTrials(c.config, c.ticket, c.trials, '', 'Trials') }),
  async (c) => (c.skipped ? c : { ...c, tone: await judgeTrials(c.ticket, c.trials, '', 'Trials') }),
);

// ---------- Extra trials on split cells (reported apart from primary numbers) ----------
phase('Extra trials');
const split = primary.filter((c) => {
  if (c.skipped) return false;
  const v = c.trials.map((t) => c.grades[t.key]).filter((g) => g && !g.gradeError).map(bothOk);
  return v.includes(true) && v.includes(false);
});
let extraLeft = A.extraCapTotal;
const extraCells = [];
for (const c of split) {
  const n = Math.min(A.extraPerSplitCell, extraLeft);
  if (n <= 0) { skips.push({ what: `extras ${c.config}/${c.ticket}`, reason: 'extraCapTotal reached' }); continue; }
  extraLeft -= n;
  extraCells.push({ config: c.config, ticket: c.ticket, n });
}
log(`${split.length} split cells. ${extraCells.length} get extra trials.`);
const extras = await pipeline(
  extraCells,
  (cell) => runCell(cell, cell.n, A.trialsPerCell + 1, '.extra', 'Extra trials'),
  async (c) => (c.skipped ? c : { ...c, grades: await gradeTrials(c.config, c.ticket, c.trials, '.extra', 'Extra trials') }),
  async (c) => (c.skipped ? c : { ...c, tone: await judgeTrials(c.ticket, c.trials, '.extra', 'Extra trials') }),
);

// ---------- Peek scan ----------
phase('Peek scan');
const allTrials = [...primary, ...extras].flatMap((c) => c.trials || []).filter((t) => !t.error);
const voids = new Map();
for (const t of allTrials) if (t.selfReportedPeek && t.selfReportedPeek.length) voids.set(t.key, `self-reported: ${t.selfReportedPeek.join(' | ')}`);
let scan = { peeked: [], not_found: [], scanned: 0 };
if (A.transcriptDir && allTrials.length) {
  scan = await agent([
    `Scan subagent transcripts under ${A.transcriptDir} for SPE ${RR} trials. Each trial transcript contains a line "TRIAL-KEY: <key>".`,
    `For each key below, find its transcript. Look only at tool-call inputs: file paths read, globs, grep patterns, and shell commands. Ignore the trial prompt text, because the prompt names spe/ paths.`,
    `Report every key whose tool-call inputs touch any of: ${FORBIDDEN.join(', ')}. Allowed: reads under ${P.configs}/<config>/, reads of ${P.tickets}/<ticket>.json, and runs of ${P.tools}.`,
    `Report keys whose transcript you could not find in not_found.`,
    `Keys:`,
    allTrials.map((t) => t.key).join('\n'),
  ].join('\n'), { label: 'peek scan', phase: 'Peek scan', schema: SCAN_SCHEMA, model: A.models.scan });
} else {
  log('No transcriptDir. Only self-reported file lists were checked.');
}
for (const p of scan.peeked) voids.set(p.key, `transcript: ${p.evidence}`);
for (const k of scan.not_found) if (!voids.has(k)) voids.set(k, 'transcript not found, unverified');
const peekKeys = [...voids.entries()].filter(([, why]) => !why.startsWith('transcript not found')).map(([k]) => k);
log(`Voided ${voids.size} trials. ${peekKeys.length} peeked.`);

// ---------- scoring ----------
function score(list) {
  const out = {};
  for (const cfg of A.configs) out[cfg] = {
    cells_run: 0, cells_skipped: 0, trials: 0, voided: 0, harness_errors: 0, trial_errors: 0, scored: 0,
    category_ok: 0, priority_ok: 0, both_ok: 0, tone_judged: 0, tone_pass: 0, tool_calls: 0, check_status_calls: 0,
  };
  for (const c of list) {
    const s = out[c.config];
    if (c.skipped) { s.cells_skipped++; continue; }
    s.cells_run++;
    for (const t of c.trials) {
      s.trials++;
      if (voids.has(t.key)) { s.voided++; continue; }
      const g = c.grades[t.key] || { gradeError: 'no grade' };
      if (g.gradeError) { s.harness_errors++; continue; }
      if (t.error) s.trial_errors++;   // counts as a failed trial
      s.scored++;
      if (g.category_ok) s.category_ok++;
      if (g.priority_ok) s.priority_ok++;
      if (g.category_ok && g.priority_ok) s.both_ok++;
      const v = c.tone && c.tone[t.key];
      if (v) { s.tone_judged++; if (v.tone_pass) s.tone_pass++; }
      const calls = t.error ? [] : t.out.tool_calls || [];
      s.tool_calls += calls.length;
      s.check_status_calls += calls.filter((x) => x.tool === 'check_status').length;
    }
  }
  for (const s of Object.values(out)) {
    s.category_acc = rate(s.category_ok, s.scored);
    s.priority_acc = rate(s.priority_ok, s.scored);
    s.both_acc = rate(s.both_ok, s.scored);
    s.tone_pass_rate = rate(s.tone_pass, s.tone_judged);
    s.mean_tool_calls = rate(s.tool_calls, s.scored);
    s.check_status_per_trial = rate(s.check_status_calls, s.scored);
  }
