}
const primaryScore = score(primary);
const extraScore = score(extras);
const cellTable = primary.map((c) => ({
  config: c.config, ticket: c.ticket, skipped: !!c.skipped,
  both: (c.trials || []).map((t) => (voids.has(t.key) ? 'void' : bothOk(c.grades[t.key]) ? 1 : 0)),
  tone: (c.trials || []).map((t) => (c.tone && c.tone[t.key] ? (c.tone[t.key].tone_pass ? 1 : 0) : null)),
