const analysis = await agent([
  `You are the failure analyst for SPE ${RR}. Read ${P.prediction}, ${P.plan}, and spe/failures.md. Do not edit any file.`,
  `Primary numbers use the first ${A.trialsPerCell} trials per cell. Extras on split cells are separate and must not change verdicts.`,
